def validate_tags(tags: list, allowed: list) -> list:
    """闭集校验：只保留在 allowed 里的标签，预设外的丢弃。
    返回去重后的合法标签列表，保持顺序。
    """
    def normalize(tag: str) -> str:
        return tag.strip().lower()

    allowed_normalized = {normalize(tag) for tag in allowed}
    seen = set()
    result = []
    for tag in tags:
        norm = normalize(tag)
        if norm in allowed_normalized and norm not in seen:
            seen.add(norm)
            result.append(norm)
    return result

